ument).on('change', '.size-checkbox', function (e) {
                let chip = $(this).closest('.size-set-chip');
                let wrapper = $(this).closest('.size-wrapper');
                let productId = chip.data('product-id');
                let sizeId = chip.data('size-id');
                let mrp = chip.data('mrp');
                let key = productId + '-' + sizeId;
                let isChecked = $(this).prop('checked');

                chip.toggleClass('selected', isChecked);
                wrapper.find('.color-options').toggle(isChecked);

                if (isChecked) {
                    let colorIds = [];
                    wrapper.find('.color-checkbox:checked').each(function() {
                        colorIds.push($(this).val());
                    });
                    selectedItems[key] = { productId, sizeId, mrp, discount: 0, barcodeCount: 1, colorIds: colorIds };
                } else {
                    delete selectedItems[key];
                }
                renderSelectedList();
            });

